optimization-iteration.patch:
diff --git a/tools/bot-evaluation/src/host.rs b/tools/bot-evaluation/src/host.rs
index 4593133d..6e4ddb59 100644
--- a/tools/bot-evaluation/src/host.rs
+++ b/tools/bot-evaluation/src/host.rs
@@ -32,11 +32,11 @@ impl Host {
         std::thread::spawn(move || {
             let mut reader = BufReader::new(output);
             loop {
-                let mut line = String::new();
+                let mut line = Vec::new();
                 match reader
                     .by_ref()
                     .take(64 * 1024 * 1024 + 1)
-                    .read_line(&mut line)
+                    .read_until(b'\n', &mut line)
                 {
                     Ok(0) => {
                         let _ = tx.send(Err("Engine host exited".into()));
@@ -48,7 +48,7 @@ impl Host {
                             break;
                         }
                         if tx
-                            .send(serde_json::from_str(&line).map_err(|e| e.to_string()))
+                            .send(serde_json::from_slice(&line).map_err(|e| e.to_string()))
                             .is_err()
                         {
                             break;
